                    // Several keys at once never answer an approval: their text goes to the draft, as a paste does.
                    _ if !burst_may_answer(app.state.approval_id().is_some(), keys.len()) => {
                        app.state.on_paste(&burst_draft_text(&keys));
                        None
                    }
                    Some(text) => {
                        app.state.on_paste(&text);
                        None
                    }
                    None => {
                        let mut last = None;
                        for key in keys {
                            if let Some(action) = app.state.on_key(key) {
                                last = Some(action);
                                break;
                            }
                        }
                        last
                    }
                }
            }
            TermEvent::Key(key) if key.kind == KeyEventKind::Press => app.state.on_key(key),
            TermEvent::Paste(text) => {
                app.state.on_paste(&text);
                None
            }
            TermEvent::Resize(_, _) => None,
            _ => continue,
        };
        redraw = true;
        let Some(action) = action else {
            continue;
        };
        if action == Action::Quit {
            app.state.closing = true;
            draw(terminal, app)?;
        }
        if !app.handle(action) {
            return Ok(());
        }
    }
}

