1409	    /// The approval panel's keys. `y` approves, `n` denies, `a` asks to approve every later action (`a` or Enter
1410	    /// again confirms), Enter takes the focused option, ←/→ and Tab/Shift+Tab move the focus, Esc denies. Other text
1411	    /// goes to the draft (steering), so nothing typed is lost and the letters keep answering the panel.
1412	    fn on_approval_key(&mut self, key: KeyEvent, now: Instant) -> Option<Action> {
1413	        // Scrolling the change keeps the focus (and a pending confirmation).
1414	        if matches!(key.code, KeyCode::Up | KeyCode::Down | KeyCode::PageUp | KeyCode::PageDown | KeyCode::Home | KeyCode::End) && key.modifiers.is_empty() {
1415	            self.scroll_overlay(key.code);
1416	            return None;
1417	        }
1418	        let Some(Overlay::Approval(approval)) = &mut self.overlay else {
1419	            return None;
1420	        };
1421	        approval.notice = None;
1422	        // Esc denies (the safe direction), and is the way out on a terminal too small to draw the panel.
1423	        if key.code == KeyCode::Esc {
1424	            return self.decide(Verdict::Denied);
1425	        }
1426	        // Keys count only unmodified (letters may be shifted, Shift+Tab is a key of its own): chords are editing
1427	        // commands, never answers.
1428	        let bare = key.modifiers.is_empty();
1429	        let letter = (key.modifiers - KeyModifiers::SHIFT).is_empty();
1430	        let at = APPROVAL_OPTIONS.iter().position(|option| *option == approval.focus).unwrap_or(0);
1431	        let last = APPROVAL_OPTIONS.len() - 1;
1432	        let moved = match key.code {
1433	            KeyCode::Left if bare => Some(at.saturating_sub(1)),
1434	            KeyCode::Right if bare => Some((at + 1).min(last)),
1435	            KeyCode::Tab if bare => Some((at + 1) % APPROVAL_OPTIONS.len()),
1436	            KeyCode::BackTab if letter => Some((at + last) % APPROVAL_OPTIONS.len()),
1437	            _ => None,
1438	        };
1439	        if let Some(to) = moved {
1440	            approval.focus = APPROVAL_OPTIONS[to];
1441	            approval.confirming = false;
1442	            return None;
1443	        }
1444	        let verdict = match key.code {
1445	            KeyCode::Enter if bare => approval.focus,
1446	            KeyCode::Char('y' | 'Y') if letter => Verdict::Approved,
1447	            KeyCode::Char('n' | 'N') if letter => Verdict::Denied,
1448	            KeyCode::Char('a' | 'A') if letter => Verdict::ApprovedForSession,
1449	            // Not an answer. Typed text goes to the draft, where it is kept for after the decision (or sent as
1450	            // steering); it cancels a pending confirmation.
1451	            KeyCode::Char(c) if letter => {
1452	                approval.confirming = false;
1453	                approval.last_text = Some(now);
1454	                self.composer.insert(c.encode_utf8(&mut [0; 4]));
1455	                return None;
1456	            }
1457	            KeyCode::Backspace if bare => {
1458	                approval.confirming = false;
1459	                approval.last_text = Some(now);
1460	                self.composer.backspace();
1461	                return None;
1462	            }
1463	            _ => return None,
1464	        };
1465	        // In a run of typing a `y`, `n` or `a` is a letter of the text (kept in the draft) and Enter is ignored: only
1466	        // a key after a pause answers.
1467	        if approval.last_text.is_some_and(|at| now.saturating_duration_since(at) < APPROVAL_TYPING_RUN) {
1468	            approval.confirming = false;
1469	            // An ignored key re-arms the run, and the wait for a full repeat window: a held key (auto-repeat arrives
1470	            // as presses) stays inert until released.
1471	            approval.last_text = Some(now);
1472	            approval.rearm_guard(now);
1473	            if let KeyCode::Char(c) = key.code {
1474	                self.composer.insert(c.encode_utf8(&mut [0; 4]));
1475	            }
1476	            approval.notice = Some(APPROVAL_TYPING);
1477	            return None;
1478	        }
1479	        // Not on screen (too small a terminal): nothing is decided that the operator cannot see.
1480	        if !approval.shown {
1481	            return None;
1482	        }
1483	        if approval.guard_until.is_some_and(|until| now < until) {
1484	            approval.notice = Some(APPROVAL_IGNORED);
1485	            // Re-armed for a full repeat window by every ignored key: a key pressed and held inside the wait is not
1486	            // answered by its own first auto-repeat (up to about a second after the press); only a fresh press after
1487	            // the key has been quiet that long answers.
1488	            approval.rearm_guard(now);
1489	            // The key was typing in flight: its letter is kept in the draft and starts the typing run, so the rest of
1490	            // the word (an `a`, `n` and then `y` of "any") is text too.
1491	            if let KeyCode::Char(c) = key.code {
1492	                approval.last_text = Some(now);
1493	                self.composer.insert(c.encode_utf8(&mut [0; 4]));
1494	            }
1495	            return None;
1496	        }
1497	        // A command that is cut off at the fold is never approved unseen.
1498	        if verdict != Verdict::Denied && !approval.read_all {
1499	            approval.notice = Some(APPROVAL_UNSEEN);
1500	            approval.rearm_guard(now);
1501	            return None;
1502	        }
1503	        // Approving every later action is never one key: it asks once, then Enter or `a` confirms, no sooner than
1504	        // `APPROVAL_CONFIRM_DELAY` after the question (a double tap or held key does not).
1505	        if verdict == Verdict::ApprovedForSession {
1506	            if !approval.confirming {
1507	                approval.focus = Verdict::ApprovedForSession;
1508	                approval.confirming = true;
1509	                approval.confirm_asked_at = Some(now);
1510	                return None;
1511	            }
1512	            if approval.confirm_asked_at.is_some_and(|at| now.saturating_duration_since(at) < APPROVAL_CONFIRM_DELAY) {
1513	                approval.notice = Some(APPROVAL_CONFIRM_JUST_OPENED);
1514	                approval.confirm_asked_at = Some(now);
1515	                return None;
1516	            }
1517	        }
1518	        self.decide(verdict)
1519	    }
