1521	    /// Records the decision on the open approval and returns the command that answers it.
1522	    fn decide(&mut self, verdict: Verdict) -> Option<Action> {
1523	        let Some(Overlay::Approval(approval)) = self.overlay.take() else {
1524	            return None;
1525	        };
1526	        let insert_idx = self.transcript.iter().rposition(|e| match e {
1527	            Entry::Tool { tool, status: ToolStatus::Running, .. } => *tool == approval.tool,
1528	            _ => false,
1529	        });
1530	        let decision_entry = Entry::Decision {
1531	            tool: approval.tool,
1532	            subject: approval.subject,
1533	            verdict,
1534	        };
1535	        match insert_idx {
1536	            Some(idx) => self.transcript.insert(idx, decision_entry),
1537	            None => self.transcript.push(decision_entry),
1538	        };
1539	        Some(Action::Send(match verdict {
1540	            Verdict::Denied => Command::Deny { id: approval.id },
1541	            verdict => Command::Approve {
1542	                id: approval.id,
1543	                always: verdict == Verdict::ApprovedForSession,
1544	            },
1545	        }))
1546	    }
