555	fn modal_block(title: &'static str) -> Block<'static> {
556	    Block::bordered()
557	        .border_type(BorderType::Rounded)
558	        .border_style(Style::default().fg(ACCENT))
559	        .title(Span::styled(
560	            title,
561	            Style::default().fg(ACCENT).add_modifier(Modifier::BOLD),
562	        ))
563	}
