565	/// Draws the approval panel: what is proposed and on what, the change itself (file changes through the shared diff
566	/// view), and the three decisions as buttons with the focused one highlighted. Returns the review's rows and the
567	/// largest useful scroll.
568	fn render_approval(frame: &mut Frame, area: Rect, approval: &Approval, depth: theme::Depth, waiting: usize) -> (usize, usize, bool) {
569	    let pal = diff_view::palette(depth);
570	    let key = Style::default().fg(ACCENT).add_modifier(Modifier::BOLD);
571	    let muted = Style::default().fg(MUTED);
572	    let width = usize::from(area.width.saturating_sub(2));
573	    let narrow = width < 60;
574	    // What is proposed, and the target.
575	    let mut head = markdown::wrap(
576	        vec![
577	            Span::styled(tool_verb(&approval.tool), Style::default().fg(Color::White).add_modifier(Modifier::BOLD)),
578	            Span::styled(format!(" {}", diff_view::safe_text(&approval.subject)), Style::default().fg(Color::White)),
579	        ],
580	        width,
581	        Vec::new(),
582	        vec![Span::raw("  ")],
583	    );
584	    let kind = match &approval.patch {
585	        Some(patch) => patch.files.first().map(|file| {
586	            let (added, removed) = file.counts();
587	            format!("{} {} · +{added} {}{removed}", match file.status {
588	                diff_view::Status::Added => "create",
589	                diff_view::Status::Deleted => "delete",
590	                _ => "change",
591	            }, diff_view::safe_text(file.path()), diff_view::MINUS)
592	        }),
593	        None if approval.tool == "run_command" => Some("run a shell command in the workspace".to_string()),
594	        None => None,
595	    };
596	    if let Some(kind) = kind {
597	        head.extend(markdown::wrap(vec![Span::styled(format!("Proposed: {kind}"), muted)], width, Vec::new(), vec![Span::raw("  ")]));
598	    }
599	    // The decisions, as buttons, each with the key that answers it; the focused one (what Enter takes) highlighted.
600	    let button = |label: &str, verdict: Verdict, hotkey: &str| -> Vec<Span<'static>> {
601	        let focused = approval.focus == verdict;
602	        let style = if focused {
603	            Style::default().fg(Color::Black).bg(ACCENT).add_modifier(Modifier::BOLD)
604	        } else {
605	            Style::default().fg(Color::White).bg(SURFACE)
606	        };
607	        let marker = if focused { "▸" } else { " " };
608	        vec![Span::styled(format!("{marker}{hotkey} {label} "), style), Span::raw(" ")]
609	    };
610	    let mut buttons = Vec::new();
611	    buttons.extend(button("Approve", Verdict::Approved, "y"));
612	    buttons.extend(button(if narrow { "All later" } else { "Approve all later actions" }, Verdict::ApprovedForSession, "a"));
613	    buttons.extend(button("Deny", Verdict::Denied, "n"));
614	    let mut footer = markdown::wrap(buttons, width, Vec::new(), Vec::new());
615	    let hint = match approval.notice {
616	        // A key did not answer: say which and why, instead of silently doing nothing.
617	        Some(notice) => vec![Span::styled(if narrow { notice.split(" — ").next().unwrap_or(notice) } else { notice }, Style::default().fg(Color::Yellow))],
618	        None if approval.confirming => if narrow {
619	            vec![Span::styled("enter", key), Span::styled(" confirms all · ", muted), Span::styled("esc", key), Span::styled(" denies", muted)]
620	        } else {
621	            vec![
622	                Span::styled("approve this and every later action (switches to auto)? ", Style::default().fg(Color::Yellow)),
623	                Span::styled("enter", key),
624	                Span::styled(" confirms · ", muted),
625	                Span::styled("←→", key),
626	                Span::styled(" back · ", muted),
627	                Span::styled("esc", key),
628	                Span::styled(" denies", muted),
629	            ]
630	        },
631	        None => if narrow {
632	            vec![Span::styled("y", key), Span::styled("/", muted), Span::styled("n", key), Span::styled(" or ", muted), Span::styled("←→ enter", key), Span::styled(" · ", muted), Span::styled("esc", key), Span::styled(" denies", muted)]
633	        } else {
634	            vec![
635	                Span::styled("y", key),
636	                Span::styled(" approve · ", muted),
637	                Span::styled("n", key),
638	                Span::styled(" deny · ", muted),
639	                Span::styled("←→", key),
640	                Span::styled("/", muted),
641	                Span::styled("tab", key),
642	                Span::styled(" move, ", muted),
643	                Span::styled("enter", key),
644	                Span::styled(" takes ▸ · ", muted),
645	                Span::styled("↑↓", key),
646	                Span::styled(" scroll · ", muted),
647	                Span::styled("esc", key),
648	                Span::styled(" denies", muted),
649	            ]
650	        },
651	    };
652	    let lines: Vec<Line> = match &approval.patch {
653	        Some(patch) => {
654	            let geo = Geometry { width, indent: 1, num_width: diff_view::patch_num_width(patch) };
655	            diff_view::panel_rows(patch)
656	                .into_iter()
657	                .filter(|row| !matches!(row, diff_view::Row::File(_) | diff_view::Row::Blank))
658	                .flat_map(|row| diff_view::panel_row_lines(patch, row, geo, Fit::Wrap, &pal))
659	                .collect()
660	        }
661	        // Text rows (commands, scripts, arguments) wrap to the panel so no part of a line is cut off at its edge.
662	        None => approval
663	            .lines
664	            .iter()
665	            .flat_map(|line| markdown::wrap(vec![Span::styled(expand_tabs(&line.text).into_owned(), line_style(line.kind))], width, Vec::new(), vec![Span::raw("    ")]))
666	            .collect(),
667	    };
668	    // The panel fits its content (heading, the change, decisions) and never needs more than the area; the hint row
669	    // is the first thing dropped when space is short, then the gap rows.
670	    let available = usize::from(area.height.saturating_sub(2));
671	    let fixed = head.len() + footer.len();
672	    // The hint or notice never takes a row the text needs: text that must be folded needs two body rows (one row and
673	    // the fold marker), so on a short terminal a refusal's notice is left out and the marker explains the refusal.
674	    let body_min = if approval.patch.is_none() && lines.len() > 1 { 2 } else { usize::from(!lines.is_empty()) };
675	    let with_hint = available >= fixed + 1 + 1 + body_min;
676	    if with_hint {
